import { useEffect } from "react";

const JitsiMeet = ({ roomName, displayName, onEnd }) => {
  useEffect(() => {
    let api = null; // <--- DECLARADO AQUÍ, para que todas las funciones lo vean

    function startConference() {
      const domain = "meet.jit.si";
      const options = {
        roomName: roomName,
        parentNode: document.getElementById("jitsi-container"),
        width: "100%",
        height: 600,
        userInfo: {
          displayName: displayName || "Invitado"
        },
        configOverwrite: {
          startWithAudioMuted: false,
          startWithVideoMuted: false,
        },
        interfaceConfigOverwrite: {
          TOOLBAR_BUTTONS: [
            "microphone", "camera", "closedcaptions", "desktop", "fullscreen",
            "fodeviceselection", "hangup", "profile", "chat", "raisehand",
            "tileview"
          ],
        }
      };
      api = new window.JitsiMeetExternalAPI(domain, options);

      // Evento cuando el usuario sale
      api.addListener("readyToClose", () => {
        if (onEnd) onEnd();
      });
    }

    // Carga el script solo si no está presente
    if (!window.JitsiMeetExternalAPI) {
      const script = document.createElement("script");
      script.src = "https://meet.jit.si/external_api.js";
      script.async = true;
      script.onload = startConference;
      document.body.appendChild(script);
      return () => {
        document.body.removeChild(script);
        if (api) api.dispose();
        const container = document.getElementById("jitsi-container");
        if (container) container.innerHTML = "";
      };
    } else {
      startConference();
      return () => {
        if (api) api.dispose();
        const container = document.getElementById("jitsi-container");
        if (container) container.innerHTML = "";
      };
    }
    // eslint-disable-next-line
  }, [roomName, displayName]);

  return (
    <div className="bg-gray-100 rounded-xl shadow-lg border border-gray-300 mt-6 p-2 w-full flex justify-center">
      <div
        id="jitsi-container"
        className="w-full"
        style={{ minHeight: "600px" }}
      ></div>
    </div>
  );
};

export default JitsiMeet;
